('A failed check prevents sign-on. Filing this inspection will take the appliance out of service and notify command.', 'xh', 'Uvavanyo olungaphumelelanga luthintela ukungena emsebenzini. Ukungeniswa kolu hlolo kuya kukhupha isixhobo emsebenzini kwaye kwazise abaphathi.'),
('A failed check sends the bodycam for repair. You will need to choose another one, or say why you have none.', 'xh', 'Uvavanyo olungaphumelelanga luthumela ikhamera yomzimba ukuba ilungiswe. Kuya kufuneka ukhethe enye, okanye uxele ukuba kutheni ungenayo.'),
('A failed safety check or damage sends the firearm to the armourer. You will need to select another one.', 'xh', 'Uvavanyo lokhuseleko olungaphumelelanga okanye umonakalo luthumela umpu kumphathi wezixhobo. Kuya kufuneka ukhethe omnye.'),
('A failed vehicle check takes the ambulance off the road when you file. Continue to the stock check and describe the fault there.', 'xh', 'Ukuhlolwa kwesithuthi okungaphumelelanga kukhupha i-ambulensi endleleni xa ufayila. Qhubeka uye kuhlolo lwempahla uze uchaze impazamo apho.'),
