on conflict (key, lang) do update
   set text = excluded.text, status = 'approved', drafted_by = 'criti', updated_by_name = excluded.updated_by_name,
       updated_at = now(), approved_by = null, approved_by_name = excluded.approved_by_name, approved_at = now()
 where not (t.status = 'approved' and t.drafted_by = 'person');

insert into public.translations as t (key, lang, text, status, drafted_by, updated_by_name, updated_at, approved_by_name, approved_at)
select v.key, v.lang, v.text, 'approved', 'criti', 'Claude', now(), 'Claude (auto-approved)', now()
from (values
('Answer all six readiness questions.', 'xh', 'Phendula yonke imibuzo emithandathu yokulungela.'),
('Answer every question honestly.', 'xh', 'Phendula yonke imibuzo ngokunyaniseka.'),
('Answer every question honestly. Your answers and submission time are recorded for supervisor review. Questions marked', 'xh', 'Phendula yonke imibuzo ngokunyaniseka. Iimpendulo zakho nexesha lokungenisa ziyabhalwa ukuze umphathi aziphonononge. Imibuzo ephawulwe'),
('Any', 'xh', 'Nayiphi na'),
('Any officer', 'xh', 'Nalaliphi na igosa'),
