('Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.', 'xh', 'Ukuvula into akuyiniki indima nantoni na ebingenakuvunywa yi-matrix yeendlela nokhuseleko lwenqanaba lomqolo — ezi nkqubo zimbini zisebenza kunye. Ukuvala enye kuyifihla naphi na kwaye kwenza iindlela zayo zeseva zale, kulo mqeshi kuphela.'),
