('I am not drawing a firearm this shift (e.g. mine is not on the armoury register). This is recorded on my start-of-shift record.', 'xh', 'Andithathi mpu kule shifti (umz. owam awukho kwirejista yendlu yezixhobo). Oku kubhalwe kwirekhodi yam yokuqala ishifti.'),
('I am not wearing a bodycam this shift. My reason is on my start-of-shift record and my supervisor sees it.', 'xh', 'Andinxibanga khamera yomzimba kule shifti. Isizathu sam sikwirekhodi yam yokuqala ishifti kwaye umphathi wam uyasibona.'),
('I checked this ambulance and its stock myself, and the answers above are accurate.', 'xh', 'Ndiyihlolile le ambulensi nempahla yayo ngokwam, kwaye iimpendulo ezingentla zichanekile.'),
('I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.', 'xh', 'Ndiyaqinisekisa ukuba ndisihlolile ngokwam esi sithuthi singentla kwaye iinkcukacha ezirekhodiweyo zichanekile ngokolwazi lwam. Naziphi na iziphene eziphawulweyo mazixelwe kumphathi okufutshane kwaye zibhalwe kwincwadi esemthethweni yepokotho.'),
('I explained the court date, and that paying the admission of guilt is a conviction and may give a criminal record.', 'xh', 'Ndichazile umhla wenkundla, kwaye ukuhlawula intlawulo yokuvuma ityala kukugwetywa kwaye kunokunika irekhodi yolwaphulo-mthetho.'),
('I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).', 'xh', 'Ndichazile isaziso nokhetho: hlawula kwiintsuku ezingama-32 ukuze ufumane isaphulelo, faka isicelo sokuhlawula ngezavenge (AARTO 04), okanye wenze isimangalo (AARTO 08).'),
('I have an activation code', 'xh', 'Ndinekhowudi yokwenza isebenze'),
('I have read the POPIA notice (version {POPIA_NOTICE_VERSION})', 'xh', 'Ndisifundile isaziso se-POPIA (inguqulelo {POPIA_NOTICE_VERSION})'),
('I have read this shift', 'xh', 'Ndikufundile oku kule shifti'),
('I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.', 'xh', 'Ndiyayazi indlela isebe lakho elisebenza ngayo kwaye ndinokufunda ibhodi ephilayo indima yakho enokuyibona. Ndibuze nantoni na, okanye undixelele into yokwenza. Ndiyayilungisa, kwaye akukho nto itshintshayo ude uqinisekise.'),
('I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.', 'xh', 'Ndiyayazi ishifti yakho, iminxeba yakho, ikhefu lakho nezixhobo zakho. Ndibuze nantoni na ngomsebenzi wakho, ngamazwi akho. Ndiyacacisa ndikubonise apho ufanele ukuya khona; wena wenza umsebenzi.'),
('I personally completed these checks and confirm that the answers and any defects recorded are accurate.', 'xh', 'Ndikugqibile ngokwam oku kuhlola kwaye ndiyaqinisekisa ukuba iimpendulo nazo naziphi na iziphene ezibhaliweyo zichanekile.'),
('I will use HikTech only for official duties and keep my password private', 'xh', 'Ndiza kusebenzisa i-HikTech kwimisebenzi esemthethweni kuphela kwaye ndigcine igama lam lokugqitha liyimfihlo'),
