('Official After-Action Reports. Filing one resolves the incident.', 'xh', 'Iingxelo Ezisemthethweni Zasemva Kwesenzo. Ukufaka enye kusombulula isiganeko.'),
('Official insignia belong to the municipality and its services, so the platform ships none — upload each department''s real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department''s colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.', 'xh', 'Iimpawu ezisemthethweni zezikamasipala neenkonzo zawo, ngoko inkqubo ayizifaki — layisha uphawu lokwenyani lwesebe ngalinye apha kwaye luvela kuyo yonke indawo ngoko nangoko. Kude kube ngoko ibheji yoonobumba bokuqala iboniswa ngemibala yelo sebe, ngoko akukho nto ibonakala ingagqitywanga. I-PNG okanye i-SVG enomva ocacileyo isebenza kakuhle; imifanekiso esisikwere ifundeka kakuhle xa incinci.'),
