('Only if there is no emergency. Why?', 'xh', 'Kuphela ukuba akukho meko kaxakeka. Kutheni?'),
('Only me', 'xh', 'Ndim kuphela'),
('Only officers who went on duty in the app after today''s start of shift are listed. Distance is straight-line from their last GPS heartbeat; ETA assumes {speedKmh} km/h with a {roadFactor}× road factor (Admin → Operations Settings).', 'xh', 'Kudweliswa kuphela amagosa angene emsebenzini kwi-app emva kokuqala kweshifti yanamhlanje. Umgama uthe ngqo ukusuka kwisignali yabo yokugqibela ye-GPS; i-ETA ithatha {speedKmh} km/h nesixhobo sendlela esiyi-{roadFactor}× (Admin → Iisetingi Zokusebenza).'),
('Only one patient', 'xh', 'Isigulana esinye kuphela'),
('Only someone senior to the member, in their department, can approve. Nobody approves their own.', 'xh', 'Ngumntu ophezulu kunelungu kuphela, kwisebe lalo, onokuvuma. Akukho mntu uzivumelayo.'),
