('Road traffic offences carry the AARTO Schedule 3 charge code and penalty; by-law offences carry the by-law section and the admission of guilt amount. Enter both from the official schedules, then verify. Changing a verified code or amount takes the verification off until someone checks it again.', 'xh', 'Amatyala endlela aphethe ikhowudi yetyala ye-AARTO Schedule 3 nesohlwayo; amatyala omthetho kamasipala aphethe icandelo lomthetho nemali yokuvuma ityala. Faka zombini ukusuka kwiishedyuli ezisemthethweni, uze uqinisekise. Ukutshintsha ikhowudi okanye imali eqinisekisiweyo kususa uqinisekiso de umntu ayijonge kwakhona.'),
('Road traffic offences on AARTO 01 notices; by-law offences on Section 56 (offender present) or Section 341 (unattended vehicle) notices. Every charge has its own FN- number, and a served notice can never be edited or deleted — only cancelled, with a reason.', 'xh', 'Amatyala endlela kwizaziso ze-AARTO 01; amatyala omthetho kamasipala kwizaziso zeCandelo 56 (owaphule umthetho ukhona) okanye zeCandelo 341 (isithuthi esingagadwanga). Ityala ngalinye linenombolo yalo ye-FN-, kwaye isaziso esinikiweyo asinakuze sihlelwe okanye sicinywe — sinokurhoxiswa kuphela, ngesizathu.'),
