('This page shows calls sent to you yourself, as a field officer sees them.', 'xh', 'Eli phepha libonisa iminxeba ethunyelwe kuwe ngokwakho, njengoko igosa lasentsimini liyibona.'),
('This phone could not be registered for dispatch notifications. Alerts still arrive while the app is open — report this so the handset can be checked.', 'xh', 'Le fowuni ayikwazanga ukubhaliselwa izaziso zokuthumela. Izilumkiso zisafika xa i-app ivuliwe — xela oku ukuze le fowuni ijongwe.'),
('This phone will not ring for a dispatch. Turn notifications on for HikTech in the device settings. Alerts still arrive instantly while the app is open.', 'xh', 'Le fowuni ayizukukhala xa kuthunyelwa. Vula izaziso ze-HikTech kwiisetingi zesixhobo. Izilumkiso zisafika ngoko nangoko xa i-app ivuliwe.'),
